import { Capacitor } from "@capacitor/core";
import { Directory, Filesystem } from "@capacitor/filesystem";
import { Share } from "@capacitor/share";

export type ExportResult = "downloaded" | "shared" | "cancelled";

/** Export names are generated by the app, never interpreted as device paths. */
export function exportFileName(name: string): string {
  const match = name.match(/^(word-atlas-[\s\S]+)\.(png|json)$/);
  if (!match) throw new Error("Unsupported export filename");
  const stem = match[1].replace(/[^a-zA-Z0-9_-]/g, "-").slice(0, 140);
  return `${stem}.${match[2]}`;
}

export function isShareCancelled(error: unknown): boolean {
  if (!error || typeof error !== "object") return false;
  const e = error as { name?: unknown; message?: unknown };
  return e.name === "AbortError" || (typeof e.message === "string" && /^share cancel(?:ed|led)\.?$/i.test(e.message));
}

function base64(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(reader.error ?? new Error("Cannot read export"));
    reader.onabort = () => reject(new Error("Export interrupted"));
    reader.onload = () => {
      const value = reader.result;
      if (typeof value !== "string" || !value.includes(",")) return reject(new Error("Invalid export data"));
      resolve(value.slice(value.indexOf(",") + 1));
    };
    reader.readAsDataURL(blob);
  });
}

/** Native files stay in the app cache so the selected app can read them after returning. */
export async function exportFile(blob: Blob, name: string, title: string, webShare = true): Promise<ExportResult> {
  const filename = exportFileName(name);
  if (Capacitor.isNativePlatform()) {
    const { uri } = await Filesystem.writeFile({
      path: `exports/${filename}`,
      directory: Directory.Cache,
      data: await base64(blob),
      recursive: true,
    });
    try {
      await Share.share({ files: [uri], title, dialogTitle: title });
      return "shared";
    } catch (error) {
      if (isShareCancelled(error)) return "cancelled";
      throw error;
    }
  }

  const file = new File([blob], filename, { type: blob.type });
  if (webShare && navigator.canShare?.({ files: [file] })) {
    try {
      await navigator.share({ files: [file], title });
      return "shared";
    } catch (error) {
      if (isShareCancelled(error)) return "cancelled";
      throw error;
    }
  }

  const link = document.createElement("a");
  const url = URL.createObjectURL(blob);
  link.href = url;
  link.download = filename;
  link.hidden = true;
  document.body.append(link);
  try {
    link.click();
  } finally {
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 2000);
  }
  return "downloaded";
}
